INSERT INTO game_knowledge (game_id, game_name, content_type, title, content, source, priority) VALUES
(1, '邺山彼处', 'info', '游戏简介', '你收到好友陈宇发来的多条奇怪消息，他为调查隐秘传闻，独自前往藏在深山里的邺山村。抵达村落短短数日，陈宇彻底失联，微信账号注销、电话关机，当地警方进山搜寻后，以普通失踪结案，不再跟进调查。但陈宇失踪前留给你的求救信息疑点重重，你坚信他的消失绝非意外。你将依靠网络检索，穿梭邺山村旅游官网、民间七闻论坛、社交帖子、村委会公告、面馆档案、公安系统等数十个仿真网页，搜集民俗仪式、李家三代人记录、后山失踪传闻、古老祭祀相关碎片线索，破解摩斯密码、文言谜题等机关，一步步拆解邺山村看似平和的旅游表象，揭开代代延续的恐怖献祭秘密。', '官方介绍', 10),
(1, '邺山彼处', 'info', '游戏特色', '【多元解谜机制】融合关键词检索、摩斯密码解码、文言诗句机关、人物档案推理、网页隐藏信息挖掘，解谜逻辑严谨不生硬。【多结局分支+隐藏彩蛋】不同选择对应多条独立结局，部分结局埋藏剧情伏笔，游戏内含隐藏彩蛋。【多网页串联交互】全程模拟真实互联网生态，覆盖旅游官网、论坛、小红书、公众号、公安档案、日志等数十种网页载体，线索分散在不同页面中，需要跨平台交叉验证。', '官方介绍', 9),
(1, '邺山彼处', 'strategy', '攻略流程 - 威信与七闻论坛', '【威信阶段】打开陈宇聊天记录，进入七闻论坛（账号是陈宇的威信号，密码是宿舍口号拼音首字母）。点击陈宇头像→威信号chenyu0912→朋友圈（宿舍口号：及格就是胜利）→邺山村。公众号→怀澄居士→新页面打开"与佛论禅"链接。新页面打开七闻论坛链接。【七闻论坛】账号：chenyu0912，密码：jgjssl。搜索"邺山村"→点击"旅游小张"并发信息→点击小红薯链接。【小红薯】手机扫描第六张图片的二维码，私信发送"邺山彼处"。新页面打开邺山村链接。', '玩家攻略', 8),
(1, '邺山彼处', 'strategy', '攻略流程 - 邺山村官网', '【景点民宿】立即预订→告示（于警官，图片显示警号3315110）。【美食】立即点餐→首页门头照片（1998.05.16开业）→面馆故事（李寿单创立，儿子李福明，孙子在大城市里读书）→留言板（ID：yeshan0578)→登录（ID:yeshan0578，密码：19980516）。【村务公开】村委会网站首页（《护林员季启任》有小惊喜）。【通知公告板块】第1个公告：档案编号MZ-SL-0027。第3个公告：大庆典，全选页面后底部有摩斯密码，解得SACR。倒数第2个公告：赵弘远（附件1：2000.01.25生；附件2：汀州市人民医院）。', '玩家攻略', 8),
(1, '邺山彼处', 'strategy', '攻略流程 - 村委会', '搜索"李寿单"→听哀乐得摩斯密码→IFICE（此处有惊悚画面+音效）。搜索"大庆典"（此处有惊悚画面）。搜索"李福明"→记下菜单上的莲花。搜索"赵弘远"→眼睛会随鼠标移动（挺惊悚的）→微博底部有小惊喜。搜索"汀州市人民医院"→报告查询→赵宏远/2000.01.25/男→急性白血病。', '玩家攻略', 8),
(1, '邺山彼处', 'strategy', '攻略流程 - 面馆管理后台', '日志管理密码：SACRIFICE（有惊悚画面+音效）→查看日志（赐福、公安）→按照李福明的菜单点击改变莲花（有惊悚画面）→随便点开一篇日志，复制去"与佛论禅"解密得：活人祭歌谣。日志中看不清的字复制粘贴就看清了，是窅爷。日志里的显示帮凶赵宏远自杀，帮凶还有老孙和阿良（阿良是大学生，结合面馆传到第三代线索，阿良叫李良）。', '玩家攻略', 8),
(1, '邺山彼处', 'strategy', '攻略流程 - 村委会二周目与公安', '【村委会】搜索"窅爷"（有惊悚画面）。搜索"赐福"→《邺山赐福》→一观二闻三执四心五首。搜索"公安"→跳转链接。【邺山公安】搜索"3315110"→于承安，身份证号381699200011176789。档案查询→于承安/3315110/381699200011176789/MZ-SL-0027→孙涛开。', '玩家攻略', 8),
(1, '邺山彼处', 'strategy', '攻略流程 - 最终阶段', '【村委会】搜索"孙涛开"→祈福目录。搜索"祈福目录"→第一条（祈福之物是陈宇，XXXX,必先奉之）。搜索"李良"→跳转浙西大学官网。【浙西大学官网】学生风采板块→李良→《扎根乡土》→复制搜索调研报告的题目→附件（邺山古寺）。【村委会】搜索"邺山古寺"→复制古寺志内容，与佛论禅解密得到一个小彩蛋→点击古寺志（奉人至窅爷则遂所求）→无求自应，XXXX)。搜索"无求自应，必先奉之"→页面底部依次点击"眼耳手心头"（有惊悚画面）→陈宇威信有新消息→随便输入内容发送。', '玩家攻略', 8),
(1, '邺山彼处', 'tip', '关键密码速查', '【七闻论坛】账号chenyu0912，密码jgjssl。【邺山面馆留言板】ID yeshan0578，密码19980516。【面馆管理后台日志】密码SACRIFICE。【摩斯密码】公告第3个解得SACR，李寿单哀乐解得IFICE。【公安警号】于承安警号3315110。【档案编号】MZ-SL-0027。', '玩家整理', 9),
(1, '邺山彼处', 'strategy', '全结局攻略', '【选择1】我去跟他们爆了→结局1：小小脑子·钢铁友谊。【选择2】对不起→结局2：袖手邺山·永失其友。【选择3】报警→结局3：尘埃落定·各自平安。', '玩家攻略', 7),
(1, '邺山彼处', 'tip', '隐藏彩蛋汇总', '【彩蛋1】村委会《护林员季启任》有小惊喜。【彩蛋2】搜索赵弘远时微博底部有小惊喜。【彩蛋3】村委会搜索"邺山古寺"，复制古寺志内容用"与佛论禅"解密可得小彩蛋。【彩蛋4】手机微信公众号回复"无求自应，必先奉之"，有小彩蛋。', '玩家整理', 6),
(1, '邺山彼处', 'info', '关键人物关系', '【陈宇】你的好友，前往邺山村调查后失踪，威信号chenyu0912。【李寿单】邺山面馆创始人。【李福明】李寿单之子。【李良（阿良）】大学生，面馆第三代，帮凶之一。【窅爷】献祭仪式核心人物。【赵宏远/赵弘远】2000.01.25生，患急性白血病，帮凶之一，后自杀。【于承安】于警官，警号3315110。【孙涛开】与档案MZ-SL-0027相关。【老孙】帮凶之一。', '玩家整理', 7);
INSERT INTO game_knowledge (game_id, game_name, content_type, title, content, source, priority) VALUES
(2, '灵异论坛调查记录', 'info', '游戏简介', '《灵异论坛调查记录》是一款论坛探索式网页解谜游戏。姐姐突然失踪后，玩家在她的电脑中发现了一个神秘的灵异论坛。通过搜索关键词、浏览帖子、查找隐藏信息，你将逐步追踪姐姐留下的线索，并揭开论坛背后令人不安的真相。游戏采用模拟电脑系统与论坛交互设计，强调真实感与沉浸感，包含多条剧情分支与五种不同结局。', '官方介绍', 10),
(2, '灵异论坛调查记录', 'info', '游戏背景', '你扮演温乔，17岁高三学生。你的姐姐温妍（温水青）失踪了。你登录了她的电脑，逐步发现了她与一个叫"七月半"的灵异论坛之间的联系，以及她失踪背后隐藏的庞大真相。核心目标：找到姐姐，带她回家。', '官方介绍', 9),
(2, '灵异论坛调查记录', 'strategy', '攻略流程 - 开局与微信', '1.电脑开机密码：1234567890（来源：前言）。2.微信聊天：明月夜，关键词：失踪。3.文件夹密码：yxzyddx（来源：微信-文件传输助手）。4.论坛密码：wyynlzdq（来源：备忘录-回收站-半年前）。5.真实姓名：温妍（来源：前言）。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '攻略流程 - 生日与联系人', '6.生日：20031213。来源：①备忘录-个人日记-半年前（都是03年出生）②备忘录-个人日记-一年前（冬月二十）③2003年冬月二十（农历）=2003年12月13日（公历）。7.微信添加联系人：lpyzzcl。来源：①论坛私聊记录-鬼不觉（推荐看知足常乐帖子）②论坛帖子-在老破小公寓撞见鬼了（可以私聊知足常乐）③论坛帖子-【七月半】论坛用户必读（可以搜索看个人主页、私聊）④用户搜索-知足常乐（得到微信号）。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '攻略流程 - 管理入口密码', '8.微信聊天：知足常乐，得知：下一步目标是拿到管理入口的密码。9.管理入口密码：普世广愿惠慈长生。来源：①文件夹-经文（八字真言：XXX愿X慈XX）②论坛帖子-【重要更新】关于论坛用户注册和发帖的几点说明（可私信管理员求助）③论坛私聊-管理员（操作：随便输入-2.咨询问题-随便选-2.仍有疑惑，关键词：合作机构）④用户搜索-合作机构-"运契"公益互助协会（关键词：宋青云）⑤用户搜索-宋青云-宋青云专访（关键词：普世广愿）⑥论坛帖子：那个在葬礼上失踪的朋友（关键词：惠什么长生）。XXX愿X慈XX+普世广愿+惠什么长生=普世广愿惠慈长生。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '攻略流程 - 何边与幸运生存者', '10.微信聊天：明月夜，得知：姐姐和室友7天前出现在南鄣市火车站。11.微信聊天：知足常乐，得知：他无法进入里论坛。12.管理员检索：何边-《奇闻调查》记者何边坠楼。来源：①里论坛帖子-寻找记忆中的一档生存综艺（关键词：幸运生存者）②管理员检索-幸运生存者-《幸运生存者》停播之谜（关键词：何边）。13.微信聊天：明月夜，得知：《幸运生存者》除了优胜者，其他人都没好下场，关键词：刘福来。14.微信聊天：知足常乐，关键词：转运符。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '攻略流程 - 里论坛密码', '15.里论坛帖子-最近总有奇怪的东西跟着我-密码：平安。来源：里论坛-供奉-随便输入。16.里论坛帖子-最近总有奇怪的东西跟着我-请愿密码：http://www.qiyuebanforum.cn/gongfengqiang/。来源：微信聊天记录-文件传输助手，关键词：惠慈天尊圆满广愿心经。17.里论坛帖子-怎样才能再见到死去的人-密码：一线牵。来源：请愿记录-一线牵-我要她回来，再也不离开我。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '攻略流程 - 神像地址', '18.管理员检索：宝幡神像-云留山神像。来源：①管理员检索-惠慈天尊圆满广愿心经-《□□□□圆满广愿心经》（关键词：广愿侍者）②管理员检索-广愿侍者-档案记录（得知：姐姐的记录人是一线牵，因为破折号=杨薇=yw，所以一线牵=ymx）③管理员检索-转运符-线上记录（得知：一线牵=于XX）④备忘录-个人日记-半年前（都是03年出生）⑤文件夹-生日礼物（爱你的梦欣=mx）所以：一线牵=ymx=于梦欣=小青鱼=室友。⑥管理员检索-于梦欣-用户档案（关键词：wy20260215）⑦管理员检索-wy20260215-温妍-考察记录（关键词：宝幡神像）。得到：神像地址-万家地图。19.打开：云留山神像-万家地图-导航-进入结局。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'tip', '关键密码速查', '【电脑开机密码】1234567890。【文件夹密码】yxzyddx。【论坛密码】wyynlzdq。【管理入口密码】普世广愿惠慈长生。【里论坛-平安帖密码】平安。【里论坛-请愿密码】http://www.qiyuebanforum.cn/gongfengqiang/。【里论坛-一线牵帖密码】一线牵。【微信联系人】lpyzzcl（知足常乐）。', '玩家整理', 9),
(2, '灵异论坛调查记录', 'strategy', '结局一 - 迷失', '操作：①选择出发。你独自出发，未告知任何人，进入云留山后迷失在原始森林中，手机电量耗尽，最终失联。两天后搜救队找到你时已无生命体征。结果：你死在了山里，没能救回姐姐。', '玩家攻略', 7),
(2, '灵异论坛调查记录', 'strategy', '结局二 - 遇害', '操作：①选择-再等等 ②微信聊天-小青鱼 ③选择-供奉。你被警告吓住，选择了"再等等"，并念出八字真言。当晚房门被敲响，门从外面被打开了——你被他们找到了。两天后，你在另一座城市的酒店房间内被发现，死状呈仪式般的姿态，警方无法解释。结果：你被天尊收走了，死在了不知名的酒店里。', '玩家攻略', 7),
(2, '灵异论坛调查记录', 'strategy', '结局三 - 失踪', '操作：①选择-再等等 ②微信聊天-小青鱼 ③选择-执迷不悟 ④微信聊天-知足常乐 ⑤选择-出发。你联系知足常乐，两人潜入云留山，躲过巡逻后到达祭坛所在村庄，但被信徒发现。黑袍人认出了知足常乐的"灵媒"身份，信徒们围上来，将其视为最完美的降灵祭体。结果：你被困，知足常乐被抓去献祭，姐妹二人都未能脱身。', '玩家攻略', 7),
(2, '灵异论坛调查记录', 'strategy', '结局四 - 同化', '操作：①选择-再等等 ②微信聊天-小青鱼 ③选择-执迷不悟 ④微信聊天-明月夜 ⑤选择-出发。你联系明月夜，他带了记者同行，顺利进入云留山。你看到了宝幡神像，被其震慑，意识恍惚，最终灵魂深处只剩下一个念头——"恭迎天尊"。与此同时，明月夜撰写了报道，将长生葬描述为一场成功的民俗文化活动，刘福来从棺中安然坐起。结果：你被神像同化，祭祀完成，姐姐没能回来。', '玩家攻略', 7),
(2, '灵异论坛调查记录', 'strategy', '结局五 - 明天', '操作：①选择-再等等 ②微信聊天-小青鱼 ③选择-执迷不悟 ④微信聊天-明月夜 ⑤微信聊天-知足常乐 ⑥选择-出发。你同时联系了知足常乐和明月夜及记者团队，众人一同进入云留山。在祭坛上，于梦欣拦在你面前，被知足常乐一句话击溃："你用执念困住了自己，也困住了陈菲。"你掀开棺盖，发现姐姐手里握着妈妈给的护身符，还活着。你把她抱了出来。结果：姐姐回来了，所有人都活着。但是...', '玩家攻略', 7);
INSERT INTO game_knowledge (game_id, game_name, content_type, title, content, source, priority) VALUES
(2, '灵异论坛调查记录', 'tip', '答案速查', '【电脑密码】1234567890。【加密文件夹密码】yxzyddx。【论坛用户名】温水青。【论坛密码】wyynlzdq。【实名姓名】温妍。【实名生日】20031213。【管理入口密码】普世广愿惠慈长生。【温妍锁帖愿望】平安。【第二篇锁帖用户ID】一线牵。【室友真实姓名】于梦欣。【温妍考察记录编号】wy20260215。【最终正确选择】执迷不悟。', '玩家整理', 10),
(2, '灵异论坛调查记录', 'strategy', '开局调查电脑', '【文件传输助手】记录两条线索：http://www.qiyuebanforum.cn/gongfengqiang/ 以及 yxzyddx。注意：供奉墙网址点击后会显示链接失效，这是正常剧情，不是卡关。yxzyddx是桌面加密文件夹的密码。【乔乔】可以看到温妍失踪前主动留下电脑密码：1234567890。【上善若水（妈妈）】记住妈妈给两姐妹各做了一枚护身符，并叮嘱一直带着。【张经理】确认温妍失踪前精神状态异常，向公司请假。【小青鱼】记录关键对话：那东西好像还在、要不我们一起去拜一拜吧、我来找你。小青鱼之后和温妍同时失踪。【明月夜（记者）】确认温妍此前正在帮助《奇闻调查》记者收集七月半论坛里的灵异事件。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '备忘录与加密文件夹', '【回收站】找到论坛密码 wyynlzdq。【个人日记】生日线索：2003年出生，农历冬月二十，换算后八位公历生日是 20031213。【待办事项】发帖求助：已完成；买车票：已完成；回家：未完成；活下去：未完成。回家和活下去会在好结局中被回收。【桌面加密文件夹】密码 yxzyddx。文件夹里三份内容：①南鄣旅游攻略（南鄣市、延盛岛、当地俗神信仰）②生日蛋糕（卡片署名"梦欣"，之后与后台的"于□□"组合成"于梦欣"）③经文（残缺内容补出八字真言：普世广愿惠慈长生，管理入口中不要加标点）。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '论坛登录与管理后台', '【登录七月半论坛】用户名：温水青，密码：wyynlzdq。【实名验证】真实姓名：温妍，生日：20031213。验证完成后，论坛搜索、私聊和管理入口会开放。【管理员私聊】依次输入：2.咨询问题 → 2.有所求 → 2.仍有疑惑。管理员回复：如果您需要进一步的帮助，可以进一步搜索本论坛的"合作机构"。【搜索合作机构】出现两条隐藏结果："运契"公益互助协会、捐助鸣谢。记录：运契创始人宋青云，泰永集团负责人张豪，泰永集团巨额捐助七月半论坛，运契长期资助庙宇修缮和民俗活动。【进入管理后台】输入八字真言：普世广愿惠慈长生。进入后可看到：隐藏帖子、锁定帖子、供奉、供奉名单、考察名单、祷告记录、档案记录。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '获得平安与解锁温妍帖子', '【获得平安】在管理后台点击"供奉"，页面提示"说出你的心愿吧！"，输入任意内容（例如"健康"），系统检测到"温水青"以前已供奉过，愿望为"平安"。因此正确答案：平安。说明：这里的"供奉"只是查看温妍账号已有的供奉状态，不会触发坏结局。【解锁温妍隐藏帖子】打开锁定帖"最近总有奇怪的东西跟在我身边"，输入愿望：平安。【阅读温妍帖子】温妍看见两个鬼：①红衣小女孩（对温妍说：我就是来找你的，我想跟你回家）②浑身湿透的男人（三十岁左右、微胖、眉毛上有痣、穿皮夹克、衣服像泡过水、能听见滴水声）。温妍的梦：牌楼、寺庙、唱"马兰开花二十一"的小女孩、自己被困在神像里、神像被砸碎、自己被烤熟分食。帖子末尾管理员给她留下一个仅本人可见的请愿链接。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '添加知足常乐与调查论坛怪谈', '【添加知足常乐】用户搜索"知足常乐"，主页简介中有聊天软件账号：lpyzzcl。添加后他会提醒：论坛存在隐藏内容、应寻找管理入口密码、他自己因为被论坛针对无法进入后台。【阅读"求助！！我被活埋了"】楼主：这里好黑啊，真实姓名：刘美佳。刘美佳被父亲用于"七天重生"仪式，最终死亡，但论坛账号之后仍然回复，声称自己已经获救。温妍看到的红衣小女孩，基本就是刘美佳。【阅读"活不下去了，一场车祸毁了我的家"】楼主：破折号。她的父母供奉蒙着红布的天尊像，想让植物人弟弟回来。最后姐姐逐渐表现得越来越像弟弟，弟弟则"奇迹般"回家。说明天尊的愿望存在替代或交换机制。【阅读"关注的探险主播好久没更新了"】楼主：天涯共此时hcx。帖中出现：三色绳、铃铛、长生牌楼、道观、红色许愿箱、《请愿》册、海边悬崖。主播死后尸体仍持续上传视频。帖中还出现"一线牵"的回复：也可能是触怒神明了。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '调查幸运生存者与明月夜线索', '【幸运生存者】搜索"幸运生存者"，重点记录：张豪（第一期冠军，后成为泰永集团负责人）、王玉萍（第二期冠军，后成为千福县官员）、彭皓天（第三期冠军，后成为东明中学校长）、宋金城（第四期录制时死亡的参赛者）、刘福来（延盛岛村长、节目实际赞助者）。节目每期13人，只有1人获胜。失败者的气运通过契约转移给获胜者。【明月夜调查线】查看明月夜新对话：温妍最后的IP在南鄣火车站，同行还有一名女性，建议在论坛搜索"失踪"。【搜索失踪】打开"女大学生遗体离奇失踪，家属悬赏20万"，死者姓名：陈菲。陈菲在南鄣暴雨中死亡，随后遗体从医院太平间神秘消失。直接搜索"陈菲"没有结果是正常的。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '调查宋青云延盛岛与管理名单', '【搜索宋青云】确认：宋青云外表异常年轻，他经常使用"普世广愿"等天尊经文用语，运契、泰永集团与论坛相互勾连。【搜索延盛岛】打开搬迁新闻，官方没有公开延盛岛居民被安置到哪里。【搜索宋金城】祭文写着：魂归天尊 身化侍者 福荫子孙。落款为宋金城之子。结合人物关系，可判断：宋金城之子 = 宋青云。温妍看到的湿漉漉男人，很可能就是死在延盛岛海边的宋金城。【查看供奉名单】温水青｜温妍｜线上请愿｜进行中；一线牵｜于□□｜女｜线下请愿｜进行中；这里好黑啊｜刘美佳｜线上请愿｜已完成；天涯共此时hcx｜胡长兴｜线上请愿｜已完成。【查看考察名单】知足常乐：天生灵媒、可能成为理想宿体、正在调查论坛、被列入危险用户名单、账号部分功能遭禁用。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '解锁一线牵与锁定于梦欣', '【解锁第二篇锁帖】打开锁定帖"怎样才能再见到死去的人？"，系统要求输入用户ID，正确答案：一线牵。不要输入：于梦欣、yixianqian、喵喵神、知足常乐、蝴蝶与飞雪。正常推理线索：一线牵曾建议温妍去道观拜拜、在主播帖中替"神明"说话、被后台标为线下请愿进行中、实名姓"于"。页面问题：一线牵的个人主页文件疑似被错误配置成了"蝴蝶与飞雪"的资料，卡住时直接输入中文：一线牵。【阅读一线牵故事】她是一名女性，最重要的朋友是陈菲，陈菲在暴雨中为了救她而死，她从小是"山神义女"，她无法接受陈菲死亡，她愿意付出任何代价再次见到陈菲。管理员删除一层回复后，她表示：我找到办法了，我很快就能再见到她。陈菲遗体失踪发生在此之后。【锁定于梦欣】线索：一线牵实名是"于□□"，蛋糕卡片署名"梦欣"，温妍的室友叫小青鱼，小青鱼和温妍一同去了南鄣。组合得到：于梦欣。确认：一线牵 = 于梦欣 = 小青鱼。档案说明：宋青云把于梦欣引入运契，于梦欣想复活陈菲，论坛利用她去接近祭体，她成功成为温妍的室友，陈菲遗体已被送往昌运村，温妍即将被用于长生葬。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '温妍考察记录与刘福来', '【打开温妍考察记录】在于梦欣档案中找到编号 wy20260215，输入后打开"温妍考察记录"。确认于梦欣做过的事：成为温妍室友、在房间中放置符咒、偷偷翻动温妍物品、利用天尊侍者制造跟踪和敲门、让温妍精神衰弱、建议她去论坛求助、引导她向天尊供奉、以旅游拜神为借口带她去南鄣。记录明确给出：南鄣云留山、宝幡神像。【调查刘福来与昌运村】搜索"刘福来"，可以看到：刘福来原是延盛岛村长，延盛岛居民后来迁到昌运村，昌运村位于云留山深处，村民仍供奉天尊，村里存在"活葬"或"长生葬"，刘福来即将举行长生葬，需要新的祭体续命。祷告记录明确说明：以温妍的寿命续刘福来之命，以温妍的气运福泽核心信徒。', '玩家攻略', 8),
(2, '灵异论坛调查记录', 'strategy', '定位祭祀地点与最终选择', '【定位祭祀地点】搜索"云留山"，打开帖子"男朋友家附近有个巨大的神像"。地点在千福县云留山，属于封禁区，有政府人员把守，神像巨大蒙着红布，身披宝幡，手机无法拍摄。点击第36楼附件"万家地图"（必须点击地图附件，才能得到祭祀地点并推进剧情）。【最终警告选择】地图打开后，小青鱼会主动联系温乔。随后电脑会受到天尊干扰，页面出现两个选项：供奉 和 执迷不悟。选择：执迷不悟。不要选择"供奉"。', '玩家攻略', 9),
(2, '灵异论坛调查记录', 'strategy', '招募盟友与好结局', '【必须招募两名盟友】选择"执迷不悟"后，暂时不要直接出发。【明月夜最终对话】把所有新对话看完，直到她明确说：我在南鄣火车站等你。她会带：南鄣本地记者、调查何边和彭皓天的资料、摄像设备、现实层面的曝光力量。【知足常乐最终对话】把所有新对话看完，直到他说：我也去。南鄣火车站见。他负责：穿越迷瘴、抵抗神像精神污染、提供符咒、看见并处理陈菲鬼魂、点醒于梦欣。【出发并触发好结局】确认两名盟友均已答应同行后，点击"现在出发"或"导航/出发"。温乔十小时后到达南鄣火车站，与明月夜、知足常乐、本地记者会合。记者身份帮助众人通过政府核查，知足常乐帮助众人避开迷瘴和神像干扰。后续自动推进：于梦欣阻止温乔 → 温乔指出陈菲鬼魂一直在她身边 → 知足常乐告诉她执念困住了陈菲 → 于梦欣崩溃 → 温乔撕开宝幡 → 打开棺椁 → 救出温妍 → 温妍手中仍握着妈妈的护身符。最终触发结局五《明天》。', '玩家攻略', 9),
(2, '灵异论坛调查记录', 'strategy', '其他四个结局', '【结局一：迷失】选择"执迷不悟"，不完成明月夜最终对话，不完成知足常乐最终对话，直接出发。结果：温乔独自进入云留山，在迷瘴中死亡。【结局二：遇害】天尊警告界面选择"供奉"。结果：温乔被天尊隔空杀害，温妍仍未获救。【结局三：失踪】选择"执迷不悟"，只完成知足常乐最终对话，不完成明月夜最终对话，出发。结果：虽然具备灵异防护，但没有记者和现实曝光力量，救援行动最终被掩盖，相关人员失踪。【结局四：同化】选择"执迷不悟"，只完成明月夜最终对话，不完成知足常乐最终对话，出发。结果：记者团队能进入现场，但没人抵抗神像精神污染，众人被同化为天尊信徒。【结局五：明天】选择"执迷不悟"，完成明月夜最终对话，完成知足常乐最终对话，再出发。结果：温妍获救，刘福来借寿失败，天尊力量衰退，泰永集团与运契被调查。', '玩家攻略', 8);
INSERT INTO game_knowledge (game_id, game_name, content_type, title, content, source, priority) VALUES
(2, '灵异论坛调查记录', 'info', '核心剧情真相', '温乔的姐姐温妍（论坛用户名温水青）失踪了。温乔登录姐姐的电脑，发现她与一个叫"七月半"的灵异论坛有联系。随着调查深入，真相逐渐浮现：七月半论坛背后是一个名为"天尊"的邪教组织，通过"长生葬"仪式为富人续命。温妍被选中成为刘福来（延盛岛村长、长生葬受益者）的"祭体"，她的寿命将被用来延续刘福来的生命，她的气运将福泽核心信徒。温妍的室友于梦欣（网名一线牵、小青鱼）是运契组织的成员，她引诱温妍入局，目的是复活自己死去的挚友陈菲。最终温乔在明月夜（记者）和知足常乐（灵媒）的帮助下，闯入云留山祭坛，救出姐姐温妍，揭穿了长生葬的真相。', '官方剧情', 10),
(2, '灵异论坛调查记录', 'info', '主要角色介绍', '【温乔】主角，17岁高三学生，温妍的妹妹，为救姐姐展开调查。【温妍/温水青】温乔的姐姐，被选中为长生葬祭体，失踪。【于梦欣/一线牵/小青鱼】温妍的室友，运契组织成员，为复活挚友陈菲而引诱温妍入局。【陈菲】于梦欣的挚友，在南鄣暴雨中为救于梦欣而死，遗体从太平间神秘消失。【知足常乐】论坛用户，微信号lpyzzcl，天生灵媒，能看见鬼魂，抵抗神像精神污染，是论坛的敌人。【明月夜】记者，帮助温妍收集七月半论坛的灵异事件，提供现实层面的曝光力量。【刘福来】延盛岛村长，《幸运生存者》节目实际赞助者，长生葬受益者，需要祭体续命。【宋青云】运契公益互助协会创始人，宋金城之子，外表异常年轻，使用天尊经文用语。【宋金城】第四期《幸运生存者》录制时死亡的参赛者，死在延盛岛海边，温妍看到的湿漉漉男人很可能就是他。【刘美佳/这里好黑啊】被父亲用于"七天重生"仪式而死，论坛账号死后仍回复，温妍看到的红衣小女孩基本就是她。【何边】《奇闻调查》记者，调查七月半论坛后坠楼身亡。', '官方剧情', 9),
(2, '灵异论坛调查记录', 'info', '关键组织与地点', '【七月半论坛】表面是灵异爱好者论坛，实为天尊邪教的信息平台，设有表面论坛和"里论坛"，管理后台可查看供奉名单、考察名单、祷告记录、档案记录。【运契公益互助协会】宋青云创立，长期资助庙宇修缮和民俗活动，实际是天尊邪教的外围组织，负责物色祭体。【泰永集团】负责人张豪，第一期《幸运生存者》冠军，巨额捐助七月半论坛。【《幸运生存者》】一档生存综艺节目，每期13人只有1人获胜，失败者的气运通过契约转移给获胜者。历届冠军后来都成为有权势的人物。【延盛岛】刘福来原来所在的岛屿，居民后来迁到昌运村。【昌运村】位于云留山深处，村民仍供奉天尊，存在"活葬"或"长生葬"。【云留山】祭祀地点，属于千福县封禁区，有政府人员把守，山中有巨大神像蒙着红布、身披宝幡，手机无法拍摄。【宝幡神像】天尊神像，具有精神污染能力，能同化靠近者。【万家地图】定位祭祀地点的关键附件。', '官方剧情', 8),
(2, '灵异论坛调查记录', 'info', '天尊邪教机制', '天尊邪教的运作机制：①通过《幸运生存者》等节目转移失败者的气运给获胜者。②通过"长生葬"仪式，用祭体的寿命为富人续命，用祭体的气运福泽核心信徒。③天尊的愿望存在"替代或交换"机制，比如"活不下去了"帖子中，姐姐逐渐变得像弟弟，弟弟则奇迹般回家。④神像具有精神污染能力，靠近者会被同化，灵魂深处只剩下"恭迎天尊"的念头。⑤死后的人可能仍以某种形式存在，比如刘美佳死后论坛账号仍回复，主播死后尸体仍上传视频。⑥红衣小女孩、湿漉漉男人等鬼魂是天尊仪式的"副作用"，温妍看到的红衣小女孩是刘美佳，湿漉漉男人是宋金城。', '官方剧情', 9),
(2, '灵异论坛调查记录', 'strategy', '结局五明天完整剧情', '【结局五：明天】温乔选择"执迷不悟"，完成明月夜和知足常乐的全部最终对话，两人答应同行。温乔十小时后到达南鄣火车站，与明月夜、知足常乐、本地记者会合。记者身份帮助众人通过政府核查，知足常乐帮助众人避开迷瘴和神像干扰。众人闯入祭坛，于梦欣拦在温乔面前，被知足常乐一句话击溃："你用执念困住了自己，也困住了陈菲。"温乔掀开棺盖，发现姐姐手里握着妈妈给的护身符，还活着。温乔把她抱了出来。结果：温妍获救，刘福来借寿失败，天尊力量衰退，泰永集团与运契被调查。所有人都活着。但是……（留白结局）', '官方剧情', 8),
(2, '灵异论坛调查记录', 'strategy', '结局一迷失完整剧情', '【结局一：迷失】温乔选择"执迷不悟"，但没有完成明月夜和知足常乐的最终对话，直接出发。温乔独自出发，未告知任何人，进入云留山后迷失在原始森林中，手机电量耗尽，最终失联。两天后搜救队找到她时已无生命体征。结果：温乔死在了山里，没能救回姐姐。', '官方剧情', 7),
(2, '灵异论坛调查记录', 'strategy', '结局二遇害完整剧情', '【结局二：遇害】温乔在天尊警告界面选择"供奉"。她被警告吓住，选择了"再等等"，并念出八字真言。当晚房门被敲响，门从外面被打开了——她被他们找到了。两天后，温乔在另一座城市的酒店房间内被发现，死状呈仪式般的姿态，警方无法解释。结果：温乔被天尊收走了，死在了不知名的酒店里。', '官方剧情', 7),
(2, '灵异论坛调查记录', 'strategy', '结局三失踪完整剧情', '【结局三：失踪】温乔选择"执迷不悟"，只完成知足常乐的最终对话，不完成明月夜的最终对话，然后出发。温乔联系知足常乐，两人潜入云留山，躲过巡逻后到达祭坛所在村庄，但被信徒发现。黑袍人认出了知足常乐的"灵媒"身份，信徒们围上来，将其视为最完美的降灵祭体。结果：温乔被困，知足常乐被抓去献祭，姐妹二人都未能脱身。', '官方剧情', 7),
(2, '灵异论坛调查记录', 'strategy', '结局四同化完整剧情', '【结局四：同化】温乔选择"执迷不悟"，只完成明月夜的最终对话，不完成知足常乐的最终对话，然后出发。温乔联系明月夜，他带了记者同行，顺利进入云留山。温乔看到了宝幡神像，被其震慑，意识恍惚，最终灵魂深处只剩下一个念头——"恭迎天尊"。与此同时，明月夜撰写了报道，将长生葬描述为一场成功的民俗文化活动，刘福来从棺中安然坐起。结果：温乔被神像同化，祭祀完成，姐姐没能回来。', '官方剧情', 7);
INSERT INTO game_knowledge (game_id, game_name, content_type, title, content, source, priority) VALUES
(1, '邺山彼处', 'info', '核心剧情真相', '你的好友陈宇为调查隐秘传闻，独自前往藏在深山里的邺山村。抵达村落短短数日，陈宇彻底失联，微信账号注销、电话关机，当地警方以普通失踪结案。你坚信他的消失绝非意外，通过穿梭邺山村旅游官网、民间七闻论坛、社交帖子、村委会公告、面馆档案、公安系统等数十个仿真网页，逐步揭开真相：邺山村代代延续着"活人祭"的恐怖献祭仪式，由"窅爷"主导，面馆李家三代人（李寿单、李福明、李良）是帮凶，公安系统的于承安、孙涛开也卷入其中。陈宇被选为"祈福之物"，成为献祭仪式的祭品。', '官方剧情', 10),
(1, '邺山彼处', 'info', '主要角色介绍', '【你】主角，陈宇的好友，为寻找失踪的陈宇展开调查。【陈宇】你的好友，威信号chenyu0912，为调查隐秘传闻前往邺山村，后被选为祈福之物失踪。【李寿单】邺山面馆创始人，献祭仪式的参与者。【李福明】李寿单之子，面馆第二代，菜单上有莲花图案。【李良/阿良】大学生，面馆第三代，帮凶之一，就读于浙西大学。【窅爷】献祭仪式的核心人物，名字在面馆日志中需复制粘贴才能看清。【赵宏远/赵弘远】2000.01.25生，患急性白血病，帮凶之一，后自杀。【于承安】于警官，警号3315110，身份证号381699200011176789，卷入献祭事件。【孙涛开】与档案MZ-SL-0027相关，涉及祈福目录。【老孙】帮凶之一。【季启任】护林员，村委会网站首页有他的小惊喜。', '官方剧情', 9),
(1, '邺山彼处', 'info', '关键地点与组织', '【邺山村】藏在深山里的村落，表面是平和的旅游地，实际代代延续着恐怖的献祭仪式。【七闻论坛】民间论坛，陈宇的账号是chenyu0912，密码jgjssl。【邺山村官网】包含景点民宿、美食、村务公开等板块，藏有大量线索。【村委会】村务管理系统，可搜索人名（李寿单、大庆典、李福明、赵弘远、窅爷、赐福、公安、孙涛开、李良、邺山古寺、无求自应必先奉之）。【邺山面馆】李寿单创立，留言板ID yeshan0578，密码19980516，管理后台日志密码SACRIFICE。【邺山公安】搜索3315110可查到于承安信息，档案查询可查MZ-SL-0027。【浙西大学官网】学生风采板块有李良的《扎根乡土》调研报告，附件为邺山古寺。【邺山古寺】献祭仪式的核心场所，"奉人至窅爷则遂所求"。【与佛论禅】用于解密的工具网站，可解密摩斯密码和文言谜题。', '官方剧情', 8),
(1, '邺山彼处', 'info', '献祭仪式机制', '邺山村的献祭仪式机制：①"祈福目录"记录祈福之物，第一条明确"祈福之物是陈宇，XXXX,必先奉之"。②"赐福"仪式有固定流程："一观二闻三执四心五首"，《邺山赐福》是仪式经文。③"眼耳手心头"是仪式的关键步骤，在页面底部依次点击可触发。④献祭通过"窅爷"完成，"奉人至窅爷则遂所求"。⑤仪式需要"活人祭"，歌谣中描述了活人祭的过程。⑥面馆日志记录了历代献祭的参与者（赐福、公安）。⑦献祭仪式需要帮凶配合，包括面馆李家、公安系统人员、老孙等。', '官方剧情', 9),
(1, '邺山彼处', 'strategy', '结局1完整剧情 - 小小脑子钢铁友谊', '【结局1：小小脑子·钢铁友谊】在最终选择时选择"我去跟他们爆了"。你选择直接对抗，用最原始的方式试图救出陈宇。结果：你成功救出陈宇，但过程中付出了代价，结局名为"小小脑子·钢铁友谊"——虽然鲁莽，但友谊坚固。', '官方剧情', 7),
(1, '邺山彼处', 'strategy', '结局2完整剧情 - 袖手邺山永失其友', '【结局2：袖手邺山·永失其友】在最终选择时选择"对不起"。你选择了退缩，放弃了救陈宇。结果：陈宇永远留在了邺山村，你失去了最好的朋友，结局名为"袖手邺山·永失其友"——袖手旁观，永远失去。', '官方剧情', 7),
(1, '邺山彼处', 'strategy', '结局3完整剧情 - 尘埃落定各自平安', '【结局3：尘埃落定·各自平安】在最终选择时选择"报警"。你选择报警，让警方介入。结果：警方介入调查，献祭仪式被揭露，相关人员被处理，陈宇获救。结局名为"尘埃落定·各自平安"——事件平息，所有人平安。', '官方剧情', 7),
(1, '邺山彼处', 'info', '完整攻略时间线', '① 打开陈宇聊天记录 → 进入七闻论坛（账号chenyu0912，密码jgjssl）→ 搜索"邺山村" → 点击"旅游小张" → 点击小红薯链接。② 小红薯：扫描第六张图片二维码，私信发送"邺山彼处" → 打开邺山村官网。③ 邺山村官网：景点民宿立即预订看告示（警号3315110）→ 美食立即点餐看门头照片（1998.05.16开业）→ 面馆故事 → 留言板登录（yeshan0578/19980516）→ 村务公开看护林员季启任 → 通知公告（档案编号MZ-SL-0027、大庆典摩斯密码SACR、赵弘远信息）。④ 村委会：搜索李寿单（哀乐摩斯密码IFICE）、大庆典、李福明（莲花）、赵弘远（眼睛随鼠标移动）、汀州市人民医院（赵宏远急性白血病）。⑤ 面馆管理后台：密码SACRIFICE → 查看日志 → 按菜单点击改变莲花 → 复制日志用"与佛论禅"解密得活人祭歌谣。⑥ 村委会二周目：搜索窅爷、赐福（一观二闻三执四心五首）、公安 → 邺山公安：搜索3315110（于承安）→ 档案查询MZ-SL-0027（孙涛开）。⑦ 村委会三周目：搜索孙涛开 → 祈福目录（祈福之物陈宇）→ 搜索李良 → 浙西大学官网 → 《扎根乡土》 → 附件邺山古寺 → 村委会搜索邺山古寺 → 古寺志解密 → 搜索"无求自应，必先奉之" → 点击眼耳手心头 → 陈宇威信新消息 → 最终选择。', '玩家整理', 9);